insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d5c848e3-9c8e-5472-a171-c6e7c5ecd23d', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '030e5a8c-5d6f-5737-a4f0-b5848bf7b506', 'abd39cf9-4802-532a-a50b-a6a5ca2632fc', 'Stagflation is…', '["Fast growth and falling prices","A budget surplus","Low inflation and low unemployment","High inflation combined with high unemployment"]'::jsonb, 'It is often caused by supply shocks such as oil price rises.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
