insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('c9bfd3e2-2807-5c06-aea5-6382f026e048', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'ba73d79a-7533-5601-a57e-3fd6b411010f', 'a4d31b37-7982-52bb-a6fe-ccc4786116bd', 'The Marshall-Lerner condition states that a depreciation will improve the current account if…', '["Exports are inelastic","Inflation is zero","The sum of PEDs for exports and imports is greater than 1","Imports are perfectly inelastic"]'::jsonb, 'Demand must be elastic enough for volumes to respond to price changes.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
