insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('250faa49-d05f-562d-acec-fa6a44839f68', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'ba73d79a-7533-5601-a57e-3fd6b411010f', 'a4d31b37-7982-52bb-a6fe-ccc4786116bd', 'The J-curve shows that after a depreciation, the current account…', '["Improves first, then worsens","Never improves","Improves immediately and permanently","Worsens first, then improves"]'::jsonb, 'Demand is inelastic in the short run, so the trade balance worsens first.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
